lish_date":null,"open_library_edition_id":"OL46848848M"},"before_row":{"id":962200008,"title":"De zeven zussen","isbn_10":"9401609373","isbn_13":"9789401609371","work_id":962100006,"cover_id":null,"language":null,"publisher":"Xander Uitgevers B.V.","publish_date":null,"open_library_edition_id":"OL46848848M"}},{"key":{"edition_id":962200008},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":962100006,"evidence":[{"url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","isbn":"9789401609371","facts":"Lucinda Riley, Maia''s story, first volume, Dutch translation of The Seven Sisters (Macmillan2014). Exact paperback9371, not ebooks or series bundle. Existing English Work8476 may duplicate identity; no merge, relink or new Work proposed. Record separate identity review instead of deleting either user''s book.","format":"paperback","language":"nld","checkedAt":"2026-10-31","sourceSha256":"242d5efb4aac3c387e5040d111ff3a96d261892ee840d77af4c52cfc34545f62"},{"url":"https://www.bibliotheek.nl/catalogus/titel.434916706.html/maia-s-verhaal/","role":"independent exact-edition and/or content identity corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000541899_De_zeven_zussen_0_0.jpg","role":"exact-edition image from its own edition block; visually checked","bytes":834318,"sha256":"200071b6417ac3da1b6e6adf443f2b4b08127f125243585c60d1f1debcee8ce0"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000541899_De_zeven_zussen_0_0.jpg","edition_id":962200008,"bound_title":"De zeven zussen","reviewed_at":"2026-10-31T00:00:00+00:00","bound_isbn13":"9789401609371","evidence_url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","review_batch":"hebban-priority-20261031","review_status":"approved","bound_language":"nld","card_cover_url":"https://metadata.isbn.nl/ie_fcache/0000541899_De_zeven_zussen_3_130_250_0_0.jpg","bound_author_id":945300758},"before_row":null},{"key":{"work_id":962100001,"language":"nl"},"seq":12,"relation":"catalog_work_descriptions","after_row":{"text":"Daniel Sempere bezoekt met zijn vader een verborgen boekenbewaarplaats in Barcelona. Daar kiest hij een roman van Julián Carax die hem niet meer loslaat. Zijn nieuwsgierigheid naar de schrijver brengt hem in contact met mensen wier levens met het boek verweven raken. Terwijl de schaduw van het Franco-regime over de stad ligt, ontdekt Daniel dat het verleden niet afgesloten is. Zijn zoektocht naar een auteur verandert zo ook zijn eigen leven.","work_id":962100001,"evidence":[{"url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"Bureau ISBN","source_type":"official_catalog","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":962300001},"before_row":null},{"key":{"work_id":962100002,"language":"nl"},"seq":13,"relation":"catalog_work_descriptions","after_row":{"text":"Een voormalig Amerikaans spion probeert zijn oude bestaan achter zich te laten. Een moord in een hotel in Manhattan brengt hem echter opnieuw in beweging: de dader lijkt gebruik te hebben gemaakt van kennis uit zijn eigen boek over forensisch onderzoek. Het onderzoek groeit uit tot een jacht op een onbekende tegenstander. Onder de codenaam Pelgrim moet hij achterhalen welke dreiging achter de afzonderlijke aanwijzingen schuilgaat en hoe die kan worden gestopt.","work_id":962100002,"evidence":[{"url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"Bureau ISBN","source_type":"official_catalog","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":962300002},"before_row":null},{"key":{"work_id":962100003,"language":"nl"},"seq":14,"relation":"catalog_work_descriptions","after_row":{"text":"Een bijzondere treinreis brengt Harry Potter naar Zweinstein, een school waar magie deel uitmaakt van het dagelijks leven. Hij krijgt lessen in toverdranken, leert over bezemstelen en ontmoet een wereld vol wonderlijke mogelijkheden en gevaren. Zijn kennismaking met die wereld blijft niet bij schoolwerk alleen. Achter de vertrouwde omgeving van de school dreigt de invloed van Voldemort. Dit eerste deel volgt Harry terwijl hij zijn plaats vindt tussen nieuwe ervaringen en een gevaarlijke tegenstander.","work_id":962100003,"evidence":[{"url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"Bureau ISBN","source_type":"official_catalog","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":962300003},"before_row":null},{"key":{"work_id":962100004,"language":"nl"},"seq":15,"relation":"catalog_work_descriptions","after_row":{"text":"Twee engelen kijken terug op gebeurtenissen die zij met een bepaald doel hebben beïnvloed. Menselijke relaties en keuzes blijken deel van een groter plan waarin geschiedenis, erfelijkheid en religie samenkomen. Tegelijk stelt de roman vragen over de verhouding tussen de hemel en een mensheid die steeds meer technisch kan verklaren en beheersen. Harry Mulisch verbindt deze verschillende perspectieven in een verhaal waarin vriendschap en morele vragen een belangrijke plaats innemen.","work_id":962100004,"evidence":[{"url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"},{"url":"https://www.bibliotheek.nl/catalogus/titel.441307329.html/de-ontdekking-van-de-hemel/","role":"Content/identity corroboration"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"De Bezige Bij","source_type":"official_publisher","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":930300017},"before_row":null},{"key":{"work_id":962100005,"language":"nl"},"seq":16,"relation":"catalog_work_descriptions","after_row":{"text":"In het Parijs van 1942 wordt de jonge Sarah met haar ouders opgepakt tijdens een razzia. Haar broertje blijft verborgen achter in hun woning. Zestig jaar later onderzoekt journaliste Julia Jarmond wat er tijdens die gebeurtenissen is gebeurd. In archieven ontdekt zij verbanden die veel dichter bij haar eigen familie komen dan zij verwachtte. De twee verhaallijnen laten zien hoe een gewelddadig verleden blijft doorwerken in het leven van latere generaties.","work_id":962100005,"evidence":[{"url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"Bureau ISBN","source_type":"official_catalog","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":962300004},"before_row":null},{"key":{"work_id":962100006,"language":"nl"},"seq":17,"relation":"catalog_work_descriptions","after_row":{"text":"Na de dood van hun adoptievader verzamelen Maia en haar zussen zich bij hun ouderlijk huis aan het Meer van Genève. Een brief geeft Maia een eerste aanwijzing over haar afkomst. Haar onderzoek voert haar naar Rio de Janeiro en naar gebeurtenissen die tientallen jaren eerder ook met Parijs verbonden waren. Terwijl zij de sporen van haar familie volgt, zoekt Maia uit wat die geschiedenis voor haar eigen identiteit betekent. Dit is het eerste deel van de reeks.","work_id":962100006,"evidence":[{"url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof","checkedAt":"2026-10-31"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","reviewed_at":"2026-10-31T00:00:00+00:00","source_name":"Bureau ISBN","source_type":"official_catalog","review_batch":"hebban-priority-20261031","review_status":"approved","bound_author_id":945300758},"before_row":null}],"batch":"hebban-priority-test-20261031","project":"hlvujbrmfdlrfxdjwsmb"}'::jsonb::text,true);
