ty review instead of deleting either user''s book.","sourceSha256":"242d5efb4aac3c387e5040d111ff3a96d261892ee840d77af4c52cfc34545f62"},{"url":"https://www.bibliotheek.nl/catalogus/titel.434916706.html/maia-s-verhaal/","role":"independent exact-edition and/or content identity corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000541899_De_zeven_zussen_0_0.jpg","role":"exact-edition image from its own edition block; visually checked","sha256":"200071b6417ac3da1b6e6adf443f2b4b08127f125243585c60d1f1debcee8ce0","bytes":834318}],"review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/984567/de-zeven-zussen.html"},{"relation":"catalog_work_descriptions","key":{"work_id":962100001,"language":"nl"},"before":null,"after":{"work_id":962100001,"language":"nl","bound_author_id":962300001,"text":"Daniel Sempere bezoekt met zijn vader een verborgen boekenbewaarplaats in Barcelona. Daar kiest hij een roman van Julián Carax die hem niet meer loslaat. Zijn nieuwsgierigheid naar de schrijver brengt hem in contact met mensen wier levens met het boek verweven raken. Terwijl de schaduw van het Franco-regime over de stad ligt, ontdekt Daniel dat het verleden niet afgesloten is. Zijn zoektocht naar een auteur verandert zo ook zijn eigen leven.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","evidence":[{"url":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/97850/de-schaduw-van-de-wind.html"},{"relation":"catalog_work_descriptions","key":{"work_id":962100002,"language":"nl"},"before":null,"after":{"work_id":962100002,"language":"nl","bound_author_id":962300002,"text":"Een voormalig Amerikaans spion probeert zijn oude bestaan achter zich te laten. Een moord in een hotel in Manhattan brengt hem echter opnieuw in beweging: de dader lijkt gebruik te hebben gemaakt van kennis uit zijn eigen boek over forensisch onderzoek. Het onderzoek groeit uit tot een jacht op een onbekende tegenstander. Onder de codenaam Pelgrim moet hij achterhalen welke dreiging achter de afzonderlijke aanwijzingen schuilgaat en hoe die kan worden gestopt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","evidence":[{"url":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/433510/ik-ben-pelgrim.html"},{"relation":"catalog_work_descriptions","key":{"work_id":962100003,"language":"nl"},"before":null,"after":{"work_id":962100003,"language":"nl","bound_author_id":962300003,"text":"Een bijzondere treinreis brengt Harry Potter naar Zweinstein, een school waar magie deel uitmaakt van het dagelijks leven. Hij krijgt lessen in toverdranken, leert over bezemstelen en ontmoet een wereld vol wonderlijke mogelijkheden en gevaren. Zijn kennismaking met die wereld blijft niet bij schoolwerk alleen. Achter de vertrouwde omgeving van de school dreigt de invloed van Voldemort. Dit eerste deel volgt Harry terwijl hij zijn plaats vindt tussen nieuwe ervaringen en een gevaarlijke tegenstander.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","evidence":[{"url":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/122485/harry-potter-en-de-steen-der-wijzen.html"},{"relation":"catalog_work_descriptions","key":{"work_id":962100004,"language":"nl"},"before":null,"after":{"work_id":962100004,"language":"nl","bound_author_id":930300017,"text":"Twee engelen kijken terug op gebeurtenissen die zij met een bepaald doel hebben beïnvloed. Menselijke relaties en keuzes blijken deel van een groter plan waarin geschiedenis, erfelijkheid en religie samenkomen. Tegelijk stelt de roman vragen over de verhouding tussen de hemel en een mensheid die steeds meer technisch kan verklaren en beheersen. Harry Mulisch verbindt deze verschillende perspectieven in een verhaal waarin vriendschap en morele vragen een belangrijke plaats innemen.","source_type":"official_publisher","source_name":"De Bezige Bij","source_url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","evidence":[{"url":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"},{"url":"https://www.bibliotheek.nl/catalogus/titel.441307329.html/de-ontdekking-van-de-hemel/","role":"Content/identity corroboration"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://www.debezigebij.nl/boek/de-ontdekking-van-de-hemel/"},{"relation":"catalog_work_descriptions","key":{"work_id":962100005,"language":"nl"},"before":null,"after":{"work_id":962100005,"language":"nl","bound_author_id":962300004,"text":"In het Parijs van 1942 wordt de jonge Sarah met haar ouders opgepakt tijdens een razzia. Haar broertje blijft verborgen achter in hun woning. Zestig jaar later onderzoekt journaliste Julia Jarmond wat er tijdens die gebeurtenissen is gebeurd. In archieven ontdekt zij verbanden die veel dichter bij haar eigen familie komen dan zij verwachtte. De twee verhaallijnen laten zien hoe een gewelddadig verleden blijft doorwerken in het leven van latere generaties.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","evidence":[{"url":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/69636/haar-naam-was-sarah.html"},{"relation":"catalog_work_descriptions","key":{"work_id":962100006,"language":"nl"},"before":null,"after":{"work_id":962100006,"language":"nl","bound_author_id":945300758,"text":"Na de dood van hun adoptievader verzamelen Maia en haar zussen zich bij hun ouderlijk huis aan het Meer van Genève. Een brief geeft Maia een eerste aanwijzing over haar afkomst. Haar onderzoek voert haar naar Rio de Janeiro en naar gebeurtenissen die tientallen jaren eerder ook met Parijs verbonden waren. Terwijl zij de sporen van haar familie volgt, zoekt Maia uit wat die geschiedenis voor haar eigen identiteit betekent. Dit is het eerste deel van de reeks.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","evidence":[{"url":"https://metadata.isbn.nl/984567/de-zeven-zussen.html","checkedAt":"2026-10-31","role":"Work-specific content facts, independently written Dutch summary; not edition-language proof"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-10-31T00:00:00+00:00","review_batch":"hebban-priority-20261031"},"origin":"https://metadata.isbn.nl/984567/de-zeven-zussen.html"}]'::jsonb;receipt jsonb;r jsonb;p jsonb;k jsonb;expected jsonb;prior jsonb;ids jsonb:='{}';kv record;i integer:=0;n integer;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'hebban-priority-test-20261031' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>17 then raise exception 'Exact manifest receipt required';end if;
 for p in select value from jsonb_array_elements(reviewed) loop
  i:=i+1;select count(*) into n from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if n<>1 then raise exception 'Receipt manifest sequence mismatch';end if;
  select x into r from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if r->>'relation' is distinct from p->>'relation' then raise exception 'Receipt manifest relation mismatch';end if;
  k:=p->'key';expected:=p->'after';prior:=p->'before';
  for kv in select * from jsonb_each(expected) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Receipt manifest missing parent';end if;
    expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if prior<>'null'::jsonb then execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',p->>'relation') into prior using prior;end if;
  execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into expected using expected;
  if r->'key' is distinct from k or r->'before_row' is distinct from prior or jsonb_typeof(r->'after_row') is distinct from 'object' or not coalesce((r->'after_row')@>expected,false) then raise exception 'Receipt differs from exact reviewed manifest';end if;
  if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;
 end loop;
end;$manifest_guard$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'hebban-priority-test-20261031' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>17 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;
commit;
select 'pr63_scoped_committed_recovery_complete' result,statement_timestamp()completed_at;
